                            serverRestrictionAlvMethod: "Gordic.Sml.WebClient.GSmlPolozkyFP:GetRestrictionAlv",
                            serverRestrictionAlfMethod: "Gordic.Sml.WebClient.GSmlPolozkyFP:GetRestrictionAlf",
